    const sub = this.subtotal();
    let d = 0;
    for (const disc of this.discounts) {
      if (disc.type === 'percent') d += sub * (disc.value / 100);
      else d += disc.value;
    }
    return round(Math.min(d, sub));
  }

  tax() { return round((this.subtotal() - this.discountTotal()) * this.taxRate); }
  total() { return round(this.subtotal() - this.discountTotal() + this.tax()); }
  itemCount() { let n = 0; for (const i of this.items.values()) n += i.quantity; return n; }

  toJSON() {
    return {
