    return this._run(cartId, async () => {
      const cart = await this.getCart(cartId);
      cart.updateQuantity(productId, quantity);
      await this.repo.save(cart);
      this.events.emit('cart.item.updated', { cartId, productId, quantity });
      return cart;
    });
